/*L05026*/   speakerEl.textContent=speaker;setImage(img,versionedPlay(image||'play/02.png'),'');img.alt=speaker||'';choices.innerHTML='';overlay.classList.add('facility-line-talk','text-safe-v96');overlay.hidden=false;
/*L05027*/   for(const raw of pages){const page=facilityTextV96(raw),n=[...page].length;textEl.textContent=page;textEl.dataset.lineLength=String(n);overlay.style.setProperty('--facility-card-width',`${n<=13?330:n<=22?370:420}px`);textEl.style.setProperty('--facility-line-font',n>=38?'13px':n>=28?'14px':n>=20?'15px':'16px');await new Promise(resolve=>{let ready=false;const timer=setTimeout(()=>ready=true,90);const next=e=>{if(!ready)return;e?.preventDefault?.();e?.stopPropagation?.();clearTimeout(timer);overlay.removeEventListener('pointerup',next,true);resolve();};overlay.addEventListener('pointerup',next,{capture:true,passive:false});});await fixedDelay(80);}
