/*L05033*/   const box=$('#castleSpeech');if(!box)return;const clean=facilityTextV96(text),n=[...clean].length;
/*L05034*/   box.className=`castle-speech side-${side} text-safe-v96`;$('small',box).textContent=speaker;$('p',box).textContent=clean;box.hidden=false;
