/*L06499*/ function figureOwnCapV115(f){return FIGURE_OWN_CAP_V115[f?.rarity]||1;}
/*L06500*/ function figureOverflowRubyV115(f){return FIGURE_OVERFLOW_RUBY_V115[f?.rarity]||0;}
/*L06501*/ function figureRubyCostV115(f){return FIGURE_RUBY_COST_V115[f?.rarity]||9999;}
/*L06502*/ function mobPieceDuplicateCapV115(f){return MOB_PIECE_DECK_CAP_V115[f?.rarity]||1;}
/*L06503*/ function rubyOwnedV115(){return Math.max(0,Number(state.meta?.rubies)||0);}
/*L06504*/ function setRubyV115(v){if(!state.meta)state.meta={};state.meta.rubies=Math.max(0,Math.round(Number(v)||0));}
