/*L06506*/ /* Test MAX obeys the same ownership ceilings so it cannot recreate impossible 99-copy inventories. */
/*L06507*/ const _fillTestItemsV115Base=fillTestItemsV100;
/*L06508*/ fillTestItemsV100=function(){_fillTestItemsV115Base();for(const f of FIGURES){if(f.pending)continue;state.meta.figures[f.id]=figureOwnCapV115(f);if(!state.meta.figureOrder.includes(f.id))state.meta.figureOrder.push(f.id);}};
