/*L06510*/ function migrateFigureInventoryV115(){if(!state.meta)return;if(state.meta.figureInventoryV115Migrated){if(state.meta.rubies==null)state.meta.rubies=0;return;}if(!state.meta.figures)state.meta.figures={};if(!Array.isArray(state.meta.figureOrder))state.meta.figureOrder=[];let ruby=Math.max(0,Number(state.meta.rubies)||0);const isTestMax=!!(state.test?.enabled&&state.test?.itemsMax);for(const f of FIGURES){const have=figureOwned(f.id),cap=figureOwnCapV115(f);if(have>cap){if(!isTestMax)ruby+=(have-cap)*figureOverflowRubyV115(f);state.meta.figures[f.id]=cap;}if(figureOwned(f.id)>0&&!state.meta.figureOrder.includes(f.id))state.meta.figureOrder.push(f.id);}state.meta.rubies=Math.round(ruby);state.meta.figureInventoryV115Migrated=true;saveMeta();}
