/*L08526*/ renderTavernDrinkShop=function(){const root=$('#tavernDrinkShop');if(!root)return;const unlocked=unlockedDrinkIds();const wallet=$('#drinkShopCoin');if(wallet)wallet.textContent=`所持コイン ${state.coins.toLocaleString()} G`;root.innerHTML=DRINK_SETS.filter(d=>unlocked.has(d.id)).map(d=>`<button class="drink-shop-item ${drinkCount(d.id)>0?'owned':''}" data-buy-drink-v136="${d.id}" type="button"><img src="${d.image}" alt="${d.name}"><div><b>${d.name}</b><small>${d.desc}</small><em>${d.price.toLocaleString()}G / 所持 ${drinkCount(d.id)}</em></div></button>`).join('');bindImages(root);$$('[data-buy-drink-v136]',root).forEach(b=>b.onclick=()=>{const d=DRINK_SETS.find(x=>x.id===b.dataset.buyDrinkV136);if(!d)return;openCoinShopQtyV136({name:d.name,image:d.image,price:d.price,owned:()=>drinkCount(d.id),buy:async q=>addDrink(d.id,q),after:()=>{renderTavernDrinkShop();facilityTalk('ありがとうございます🎵','モブイルカエル','play/001.png');}});});};
/*L08527*/ 
/*L08528*/ /* Blacksmith weapons: same quantity UI and affordability-limited + button. */
/*L08529*/ buyBlacksmithWeapon=async function(id){const w=weaponById(id);if(!w?.price)return;if(!blacksmithShopWeapons().some(x=>x.id===w.id))return facilityTalk('その武器はまだショップに並んでいないぞ！','モブゴンゾー','play/002.png');openCoinShopQtyV136({name:w.name,image:w.image,price:w.price,owned:()=>weaponOwned(w.id),buy:async q=>addWeapon(w.id,q),after:()=>{renderHome();renderBlacksmithPopup('shop');facilityTalk('毎度！大事に使ってくれよな！','モブゴンゾー','play/002.png');}});};
/*L08530*/ 
/*L08531*/ /* Castle item shop already has a quantity panel: make + stop exactly at the affordable amount. */
/*L08532*/ renderCastleQtyPopup=function(){const it=itemData(castleQtyState.itemId),popup=$('#castleQtyPopup');if(!it||!popup)return;const maxAffordable=Math.max(0,Math.min(99,Math.floor(Math.max(0,state.coins)/Math.max(1,it.price))));let qty=Math.max(1,Math.min(99,Number(castleQtyState.qty)||1));if(maxAffordable>=1)qty=Math.min(qty,maxAffordable);castleQtyState.qty=qty;const total=it.price*qty,over=maxAffordable<1||total>state.coins;$('#castleQtyImage').src=it.image;$('#castleQtyImage').alt=it.name;$('#castleQtyName').textContent=it.name;$('#castleQtyUnitPrice').textContent=`1個 ${it.price.toLocaleString()} G / 所持 ${itemCount(it.id)}`;$('#castleQtyValue').textContent=String(qty);$('#castleQtyTotal').textContent=`${total.toLocaleString()} G`;$('#castleQtyTotal').classList.toggle('over-budget',over);$('#castleQtyWallet').textContent=`所持コイン ${state.coins.toLocaleString()} G`;$('#castleQtyMinusBtn').disabled=qty<=1||maxAffordable<1;$('#castleQtyPlusBtn').disabled=maxAffordable<1||qty>=maxAffordable;$('#castleQtyBuyBtn').disabled=over;$('#castleQtyBuyBtn').classList.toggle('over-budget',over);};
/*L08533*/ changeCastleQty=function(delta){if(!castleQtyState.itemId)return;const it=itemData(castleQtyState.itemId);if(!it)return;const max=Math.max(0,Math.min(99,Math.floor(Math.max(0,state.coins)/Math.max(1,it.price))));if(max<1)return renderCastleQtyPopup();castleQtyState.qty=clamp((Number(castleQtyState.qty)||1)+delta,1,max);renderCastleQtyPopup();};
